<x-layouts.admin :title="$application->exists ? 'Edit application draft' : 'Prepare opportunity application'"><div class="card"><p class="eyebrow">{{ $opportunity->category->name }}</p><h2>{{ $opportunity->title }}</h2><p>{{ $opportunity->eligibility_text }}</p><p>Save a draft before uploading documents. Each participating group member must consent to the current content before submission.</p></div><form class="card innovation-form" method="POST" action="{{ $application->exists ? route('opportunity-applications.update',$application) : route('opportunity-applications.store',$opportunity) }}" data-group-application>@csrf @if($application->exists)@method('PUT')@endif
<label>Institution context<select name="institution_id" @disabled($application->exists)>@foreach($memberships as $m)<option value="{{ $m->institution_id }}" @selected(old('institution_id',$application->institution_id)==$m->institution_id)>{{ $m->institution->name }}</option>@endforeach</select></label>@if($application->exists)<input type="hidden" name="institution_id" value="{{ $application->institution_id }}">@endif
<label>Apply as<select name="group_id" data-application-group @disabled($application->exists)><option value="">Individual applicant</option>@if($opportunity->allow_groups)@foreach($groups as $group)<option value="{{ $group->id }}" @selected(old('group_id',$application->group_id)==$group->id)>{{ $group->name }} · {{ $group->institution->name }}</option>@endforeach @endif</select></label>@if($application->exists)<input type="hidden" name="group_id" value="{{ $application->group_id }}">@endif
@if($opportunity->allow_groups)@foreach($groups as $group)<fieldset data-participant-group="{{ $group->id }}"><legend>Participants · {{ $group->name }}</legend><p>Select members who will participate. Each will receive an in-app consent request; no private profile fields are copied automatically.</p>@foreach($group->members as $member)<label class="check-row"><input type="checkbox" name="group_participants[{{ $group->id }}][]" value="{{ $member->membership->user_id }}" @checked(in_array($member->membership->user_id,old('group_participants.'.$group->id,$application->group_id===$group->id ? ($application->participant_ids ?? []) : [auth()->id()])))>{{ $member->membership->user->name }}</label>@endforeach</fieldset>@endforeach @endif
<label>Relevant authorised project (optional)<select name="project_id"><option value="">No project reference</option>@foreach($projects as $project)<option value="{{ $project->id }}" @selected(old('project_id',$application->project_id)==$project->id)>{{ $project->title }}</option>@endforeach</select></label>
@foreach(['motivation'=>'Personal or group motivation','skills'=>'Relevant skills','project_summary'=>'Project summary to share with reviewers (optional)'] as $key=>$label)<label>{{ $label }}<textarea name="{{ $key }}" rows="4" @required($key==='motivation')>{{ old($key,$application->$key) }}</textarea></label>@endforeach
<h2>Opportunity questions</h2>@foreach($questions as $question)@php($value=old('answers.'.$question->id,$answers[$question->id] ?? ''))
@if($question->type==='document')<p><strong>{{ $question->label }}</strong> · {{ $question->required ? 'Required document' : 'Optional document' }}. Upload it from the application detail page after saving this draft.</p>
@elseif(in_array($question->type,['boolean','select']))<label>{{ $question->label }}{{ $question->required ? ' (required)' : '' }}<select name="answers[{{ $question->id }}]"><option value="">Choose an answer</option>@foreach($question->type==='boolean' ? ['yes','no'] : (json_decode($question->options,true) ?? []) as $option)<option @selected($value===$option)>{{ $option }}</option>@endforeach</select></label>
@elseif($question->type==='textarea')<label>{{ $question->label }}<textarea name="answers[{{ $question->id }}]" rows="4">{{ $value }}</textarea></label>
@else<label>{{ $question->label }}<input name="answers[{{ $question->id }}]" type="{{ $question->type==='number' ? 'number' : 'text' }}" @if($question->type==='number')step="any"@endif value="{{ $value }}"></label>@endif @endforeach
@include('career.application-select')
